/**
 * Shared helpers for WorkflowBuilder settings toggle and WorkflowLicense.
 *
 * Both components use the same subscription dialog flow and setting store
 * interactions. Extracted to avoid duplicating the logic.
 */
import { notify } from 'src/components/notifications/notify';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { CONSTANTS } from 'src/constants';
import { isSandboxEnvironment } from 'src/pages/APIs';
import { authApiService } from 'src/services';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import {
  filterPlansByEnvironment,
  findCheapestPlanForApp,
  isSubscriptionForThisApp,
} from 'src/pages/Settings/Components/Subscription/subscriptionDialogHelpers';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

export const WORKFLOW_SETTING_NAME = 'WORKFLOW_BUILDER_MODULE_SETTING';
export const WORKFLOW_CELERY_SETTING_NAME = 'WORKFLOW_CELERY_SETTING';
export const WORKFLOW_DOC_FLOW_KEY = CONSTANTS.docflow;
export const ADVANCED_WORKFLOW_SETTING_NAME = 'ADVANCED_WORKFLOW_MODULE_SETTING';
export const ADVANCED_WORKFLOW_APP_KEY = CONSTANTS.docflow_advanced;

// ---------------------------------------------------------------------------
// Context interface — both components supply this via `this`
// ---------------------------------------------------------------------------

export interface WorkflowBuilderContext {
  user_settings: dynamicObj;
  show_popup: boolean;
  loading: boolean;
  updateSetting: (key: string, value: any) => Promise<void>;
  showLoading: () => void;
  hideLoading: () => void;
  $t: (key: string) => string;
}

export type ActiveDialogConfirmHandler = (
  value: any,
  chosenPlan?: any,
  plans?: any[],
) => void | Promise<void>;

export interface ActiveDialogState {
  setting: string;
  appKey: string | string[];
  preferredAppKey: string;
  manageCreate: boolean;
  confirmHandler: ActiveDialogConfirmHandler | null;
}

export interface CombinedWorkflowDialogContext extends WorkflowBuilderContext {
  activeDialog: ActiveDialogState;
}

// ---------------------------------------------------------------------------
// Extracted methods
// ---------------------------------------------------------------------------

export async function saveSettingsImpl(
  ctx: WorkflowBuilderContext,
  key: string,
  value: any,
  options: { silent?: boolean } = {},
) {
  if (!key) {
    return;
  }
  try {
    ctx.loading = true;
    ctx.showLoading();
    await ctx.updateSetting(key, value);
    if (!options.silent) {
      notify.success(ctx.$t('MSG_SAVE'));
    }
  } catch (err: any) {
    const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    notify.error(msg);
    logError(err);
  } finally {
    ctx.loading = false;
    ctx.hideLoading();
  }
}

export async function setWorkflowBuilderImpl(ctx: WorkflowBuilderContext, val: boolean) {
  try {
    if (val) {
      ctx.user_settings[WORKFLOW_SETTING_NAME] = false;
      ctx.show_popup = true;
    } else {
      await deactivateWorkflowSubscription(
        ctx,
        WORKFLOW_DOC_FLOW_KEY,
        WORKFLOW_SETTING_NAME,
      );
    }
  } catch (err: any) {
    const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    notify.error(msg);
    logError(err);
  } finally {
    ctx.hideLoading();
  }
}

export async function deactivateWorkflowSubscription(
  ctx: WorkflowBuilderContext,
  appKey: string,
  settingName: string,
): Promise<void> {
  ctx.showLoading();
  try {
    const subscriptionStore = useSubscriptionStore();
    await subscriptionStore.fetchFeatureSubscriptions();
    const activeSub = subscriptionStore.feature_subscriptions.find(
      (sub) =>
        sub.is_active && isSubscriptionForThisApp(sub.plan_key, appKey),
    );
    let cascaded: string[] = [];
    if (activeSub) {
      const result = await subscriptionStore.cancelFeatureSubscription(
        activeSub.id,
        { silent: true },
      );
      if (result === null) {
        // Skip the preference write so it doesn't drift from the still-active sub.
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }
      cascaded = result?.cascaded_cancellations ?? [];
    }

    ctx.user_settings[settingName] = false;
    await saveSettingsImpl(ctx, settingName, false, { silent: true });

    // The auth service cascades Advanced when DocFlow Standard is cancelled;
    // mirror that on the dependent module-setting.
    if (cascaded.length > 0 && settingName === WORKFLOW_SETTING_NAME) {
      ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = false;
      await saveSettingsImpl(
        ctx,
        ADVANCED_WORKFLOW_SETTING_NAME,
        false,
        { silent: true },
      );
    }

    notify.success(ctx.$t('MSG_SAVE'));
  } finally {
    ctx.hideLoading();
  }
}

export function handleSubscriptionConfirmImpl(ctx: WorkflowBuilderContext, value: any) {
  ctx.user_settings[WORKFLOW_SETTING_NAME] = value;
}

export function onLoadingSettingsChange(ctx: WorkflowBuilderContext, newVal: boolean, oldVal: boolean) {
  if (newVal === false && oldVal === true) {
    if (!ctx.user_settings[WORKFLOW_SETTING_NAME]) {
      ctx.user_settings[WORKFLOW_SETTING_NAME] = false;
    }
    if (!ctx.user_settings[WORKFLOW_CELERY_SETTING_NAME]) {
      ctx.user_settings[WORKFLOW_CELERY_SETTING_NAME] = false;
    }
    if (!ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME]) {
      ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = false;
    }
  }
}

// Returns true only when the org genuinely has (or now has) an active
// Standard sub. Returns false for both real failure (create returned null)
// AND the "no companion plan in catalog" case — callers must treat both as
// abort conditions to avoid creating Advanced without a usable Standard.
async function ensureCompanionStandardSubscription(
  plans?: any[],
): Promise<boolean> {
  const subscriptionStore = useSubscriptionStore();
  const alreadyHasStandard = subscriptionStore.feature_subscriptions.some(
    (sub: any) =>
      sub.is_active &&
      isSubscriptionForThisApp(sub.plan_key, WORKFLOW_DOC_FLOW_KEY),
  );
  if (alreadyHasStandard) return true;

  let plansToSearch = plans;
  if (!plansToSearch) {
    const allPlans = await authApiService.getSubscriptionPlans();
    plansToSearch = filterPlansByEnvironment(
      allPlans,
      isSandboxEnvironment(),
    );
  }

  const companion = findCheapestPlanForApp(
    plansToSearch,
    WORKFLOW_DOC_FLOW_KEY,
  );
  if (!companion) return false;

  const result = await subscriptionStore.createFeatureSubscription({
    plan_id: companion.id,
    start_date: new Date().toISOString(),
  });
  return result !== null;
}

// First-activation flow: both Standard plans and Advanced tiers visible,
// Advanced preselected. The dialog is configured with `manage_create=false`
// so this handler can orchestrate the create order — Standard first, then
// (only after a successful response) the Advanced sub. Picking a Standard
// plan goes through a single create.
export function configureCombinedWorkflowDialog(
  ctx: CombinedWorkflowDialogContext,
) {
  ctx.activeDialog.setting = WORKFLOW_SETTING_NAME;
  ctx.activeDialog.appKey = [WORKFLOW_DOC_FLOW_KEY, ADVANCED_WORKFLOW_APP_KEY];
  ctx.activeDialog.preferredAppKey = ADVANCED_WORKFLOW_APP_KEY;
  ctx.activeDialog.manageCreate = false;
  ctx.activeDialog.confirmHandler = async (
    value: any,
    chosenPlan?: any,
    plans?: any[],
  ) => {
    const subscriptionStore = useSubscriptionStore();
    const choseAdvanced =
      !!chosenPlan &&
      isSubscriptionForThisApp(chosenPlan.key, ADVANCED_WORKFLOW_APP_KEY);

    if (choseAdvanced && Array.isArray(plans)) {
      const standardCreated =
        await ensureCompanionStandardSubscription(plans);
      if (standardCreated === false) {
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }
      const advancedResult = await subscriptionStore.createFeatureSubscription({
        plan_id: chosenPlan.id,
        start_date: new Date().toISOString(),
      });
      if (advancedResult === null) {
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }
    } else if (chosenPlan) {
      const result = await subscriptionStore.createFeatureSubscription({
        plan_id: chosenPlan.id,
        start_date: new Date().toISOString(),
      });
      if (result === null) {
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }
    }

    handleSubscriptionConfirmImpl(ctx, value);
    await saveSettingsImpl(ctx, WORKFLOW_SETTING_NAME, value, { silent: true });

    if (choseAdvanced) {
      ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = value;
      await saveSettingsImpl(
        ctx,
        ADVANCED_WORKFLOW_SETTING_NAME,
        value,
        { silent: true },
      );
    }
  };
}

// Advanced toggle on the license view: dialog shows only Advanced tiers.
// Behavior depends on whether Standard is already fully active:
//   - Standard sub active AND Standard pref on → create only the Advanced
//     sub, flip only the Advanced pref.
//   - Otherwise (Standard sub missing or pref off) → also provision a
//     Standard companion sub and flip the Standard pref on. Advanced can't
//     function without Standard, so the pair must stay consistent.
// Deactivating Advanced never cascades to Standard; that direction belongs
// to the Standard toggle.
//
// `manageCreate=false` keeps the create call in this handler so a missed
// dialog branch (e.g. the `hasExistingSubscription` short-circuit) can't
// silently flip the preference on without actually subscribing.
export function configureAdvancedWorkflowDialog(
  ctx: CombinedWorkflowDialogContext,
) {
  ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = false;
  ctx.activeDialog.setting = ADVANCED_WORKFLOW_SETTING_NAME;
  ctx.activeDialog.appKey = ADVANCED_WORKFLOW_APP_KEY;
  ctx.activeDialog.preferredAppKey = '';
  ctx.activeDialog.manageCreate = false;
  ctx.activeDialog.confirmHandler = async (
    value: any,
    chosenPlan?: any,
  ) => {
    const subscriptionStore = useSubscriptionStore();

    // Snapshot Standard's state BEFORE mutating anything so we know whether
    // we have to bring Standard along (sub + pref) or leave it alone.
    const standardAlreadyActive =
      subscriptionStore.feature_subscriptions.some(
        (sub: any) =>
          sub.is_active &&
          isSubscriptionForThisApp(sub.plan_key, WORKFLOW_DOC_FLOW_KEY),
      );
    const standardPrefAlreadyOn =
      ctx.user_settings[WORKFLOW_SETTING_NAME] === true;
    const skipStandardWrites = standardAlreadyActive && standardPrefAlreadyOn;

    if (chosenPlan) {
      // No-op when an active Standard sub is already present; otherwise
      // provisions the cheapest Standard companion before Advanced.
      const standardOk = await ensureCompanionStandardSubscription();
      if (standardOk === false) {
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }

      const advancedResult = await subscriptionStore.createFeatureSubscription({
        plan_id: chosenPlan.id,
        start_date: new Date().toISOString(),
      });
      if (advancedResult === null) {
        notify.error(ctx.$t('save_failed_please_retry'));
        return;
      }
    }
    // chosenPlan is null when the dialog detected `hasExistingSubscription`
    // (an active Advanced sub is already present) — no new sub to create,
    // just align the local preferences below.

    ctx.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] = value;
    await saveSettingsImpl(
      ctx,
      ADVANCED_WORKFLOW_SETTING_NAME,
      value,
      { silent: true },
    );

    if (!skipStandardWrites) {
      ctx.user_settings[WORKFLOW_SETTING_NAME] = value;
      await saveSettingsImpl(
        ctx,
        WORKFLOW_SETTING_NAME,
        value,
        { silent: true },
      );
    }
  };
}
